/* oxlint-disable jsx-a11y/no-static-element-interactions */
import classNames from 'classnames';
import React, { useContext, useEffect, useState } from 'react';

import {
  RicosAlignmentContextProvider,
  RicosNodeContextProvider,
  RicosViewerContext,
} from './../../ricos-context/index.js';
import { CollapsibleListData_InitialExpandedItems } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { ROOT } from '../data-hooks.js';
import classes from '../statics/styles/collapsible-list-component-scss.js';
import { getAlignmentFromDirection } from '../utils.js';
import { CollapsibleListContextProvider } from './collapsible-list-context.js';

const CollapsibleList = ({
  node,
  nodeIndex,
  RicosNodesRenderer,
  NodeViewContainer,
}: NodeViewRendererProps) => {
  const { initialExpandedItems, expandOnlyOne } = node.collapsibleListData || {};

  const computeExpandedItems = (): Record<string, boolean> => {
    if (initialExpandedItems === CollapsibleListData_InitialExpandedItems.ALL) {
      return (node.nodes || []).reduce((acc, curr) => ({ ...acc, [curr.id]: true }), {});
    }
    if (
      initialExpandedItems === CollapsibleListData_InitialExpandedItems.FIRST &&
      node.nodes &&
      node.nodes[0]
    ) {
      return { [node.nodes[0].id]: true };
    }
    return {};
  };

  const [expandedItems, setExpandedItems] = useState<Record<string, boolean>>(computeExpandedItems);

  // Sync expanded state when initialExpandedItems changes from props
  useEffect(() => {
    setExpandedItems(computeExpandedItems());
  }, [initialExpandedItems, node.nodes?.length]);

  const toggle = (id: string) => {
    setExpandedItems(prev => {
      const isExpanded = !!prev[id];
      if (expandOnlyOne) {
        return { [id]: !isExpanded };
      }
      return { ...prev, [id]: !isExpanded };
    });
  };

  const { isPrint } = useContext(RicosViewerContext);

  const isExpanded = (id: string) => !!isPrint || !!expandedItems[id];

  const direction = node.collapsibleListData?.direction?.toLowerCase() || 'ltr';
  const alignment = getAlignmentFromDirection(direction);

  return (
    <NodeViewContainer node={node} nodeIndex={nodeIndex}>
      <div className={classNames(classes[direction], classes.listDimensions)} data-hook={ROOT}>
        <RicosAlignmentContextProvider textAlignment={alignment}>
          <RicosNodeContextProvider parentNode={node} parentIndex={nodeIndex}>
            <CollapsibleListContextProvider isExpanded={isExpanded} toggle={toggle}>
              <RicosNodesRenderer nodes={node.nodes ?? []} />
            </CollapsibleListContextProvider>
          </RicosNodeContextProvider>
        </RicosAlignmentContextProvider>
      </div>
    </NodeViewContainer>
  );
};

const CollapsibleListRenderer = ({ node, ...props }: NodeViewRendererProps) => {
  return <CollapsibleList key={node.id} node={node} {...props} />;
};

export default CollapsibleListRenderer;
