import { useEffect, useRef, useState } from 'react';

/**
 * Measures whether the expand button fits inside the image box.
 *
 * The button's footprint is fixed (its size plus the top/right inset from `image-viewer.scss`),
 * so it is measured once when first rendered; only the image box changes size at runtime. On
 * small images the button would overflow the box and, being clipped by `overflow: hidden`,
 * focusing it on click would scroll-shift the image — so it is hidden instead.
 *
 * Defaults to `fits: true` so SSR and environments without `ResizeObserver` (jsdom in tests)
 * keep showing the button; it is hidden only once a measurement proves it overflows.
 */
export const useExpandButtonFits = () => {
  const boxRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const [fits, setFits] = useState(true);

  useEffect(() => {
    const box = boxRef.current;
    const button = buttonRef.current;
    if (!box || !button || !window?.ResizeObserver) {
      return;
    }

    // Fixed button footprint: its own size plus the anchoring inset mirrored onto the opposite
    // side, so the button keeps equal breathing room on the bottom/left and never looks cramped.
    const { top, right } = window.getComputedStyle(button);
    const requiredWidth = button.offsetWidth + (parseFloat(right) || 0) * 2;
    const requiredHeight = button.offsetHeight + (parseFloat(top) || 0) * 2;

    const measure = () => {
      setFits(box.offsetWidth >= requiredWidth && box.offsetHeight >= requiredHeight);
    };

    measure();

    const observer = new ResizeObserver(measure);
    observer.observe(box);

    return () => observer.disconnect();
  }, []);

  return { boxRef, buttonRef, fits };
};
