import type { Theme } from '@wix/ambassador-ricos-v1-ricos-conversation/types';

type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends object ? DeepPartial<T[P]> : T[P];
};

export const patchTheme = (currentTheme: Theme, partialTheme: DeepPartial<Theme>): Theme => {
  return {
    ...currentTheme,
    ...partialTheme,
    typography: { ...currentTheme.typography, ...partialTheme.typography },
    button: { ...currentTheme.button, ...partialTheme.button },
  };
};
