import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS_VIEWER } from './defaults.js';
import type { HtmlPluginViewerConfig } from './types.js';
import { HTML_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export const pluginHtml: ViewerPluginCreator<HtmlPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS_VIEWER, ...config },
    type: HTML_TYPE,
    nodeViewRenderers,
  };
};
