import type { ViewerPluginCreator } from './../ricos-types/index.js';

import nodeViewDecorator from './node-view-decorator.js';
import { sketchNodeViewDecorator } from './sketch-viewer-decorator.js';
import type { TextColorPluginViewerConfig, TextHighlightPluginViewerConfig } from './types.js';
import { TEXT_COLOR_TYPE, TEXT_HIGHLIGHT_TYPE } from './types.js';

export const pluginTextColor: ViewerPluginCreator<TextColorPluginViewerConfig> = (config = {}) => {
  return {
    config,
    type: TEXT_COLOR_TYPE,
    nodeViewDecorators: [nodeViewDecorator],
  };
};

export const pluginTextHighlight: ViewerPluginCreator<TextHighlightPluginViewerConfig> = (
  config = {}
) => {
  return {
    config,
    type: TEXT_HIGHLIGHT_TYPE,
    nodeViewDecorators: [sketchNodeViewDecorator],
  };
};
