import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { LineSpacingPluginViewerConfig } from './types.js';
import { LINE_SPACING_TYPE } from './types.js';

export const pluginLineSpacing: ViewerPluginCreator<LineSpacingPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: LINE_SPACING_TYPE,
  };
};
