import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './default-settings.js';
import { nodeViewDecorators } from './nodeViewDecorators/index.js';
import type { MentionsPluginViewerConfig } from './types.js';
import { MENTION_TYPE } from './types.js';

export const pluginMentions: ViewerPluginCreator<MentionsPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: MENTION_TYPE,
    nodeViewDecorators,
  };
};
