import React, { useContext } from 'react';

import { RicosViewerContext } from './../../ricos-context/index.js';
import type { LinkPreviewNode } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { LinkPreviewViewer } from './link-preview-viewer.js';

export const LinkPreview = ({ node, nodeIndex, NodeViewContainer }: NodeViewRendererProps) => {
  const { helpers } = useContext(RicosViewerContext);
  return (
    <NodeViewContainer node={node} nodeIndex={nodeIndex}>
      <LinkPreviewViewer node={node as LinkPreviewNode} helpers={helpers} />
    </NodeViewContainer>
  );
};

// For loadable component
export default LinkPreview;
