import classNames from 'classnames';
import type { CSSProperties, FC } from 'react';
import React, { useContext } from 'react';

import { RicosNodeContextProvider, RicosViewerContext } from './../ricos-context/index.js';
import type { Node as RichContentNode } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { BackgroundImage, Background, LayoutNode } from './../ricos-schema/next-schema/index.js';
import type { NodeViewRenderer, NodeViewRendererProps } from './../ricos-types/index.js';
import { resolveBackwardCompatOverlay } from './../_shared/resolve-backward-compat-overlay.js';
import { getImageSrc } from './../wix-rich-content-common/lib/image-utils.js';

import { gradientToCss } from '../_shared/gradient-to-css.js';
import { hexToRgba } from '../theme-utils/color-utils.js';
import viewerStyles from './card-viewer-scss.js';
import editorStyles from './card-scss.js';
import {
  getCardBackgroundColorCssVar,
  getPageSizeByFormat,
  isTransparentCardBackgroundColor,
} from './shared-with-viewer.js';
import type { CardHeaderProps, CardPluginViewerConfig, CardViewerMode } from './types.js';

const isHeaderLayout = (node: RichContentNode | undefined): boolean =>
  !!node &&
  node.type === Node_Type.LAYOUT &&
  (node as LayoutNode).layoutData?.banner?.position === 'TOP';

const isFooterLayout = (node: RichContentNode | undefined): boolean =>
  !!node &&
  node.type === Node_Type.LAYOUT &&
  (node as LayoutNode).layoutData?.banner?.position === 'BOTTOM';

/**
 * Mirror the card-converter's CARD_HEADER / CARD_CONTENT / CARD_FOOTER slotting:
 * the first top-banner layout goes into the header slot, the first bottom-banner
 * layout goes into the footer slot, everything else is the content.
 */
const splitCardChildren = (nodes: RichContentNode[]) => {
  const header = nodes.find(isHeaderLayout);
  const footer = nodes.find(isFooterLayout);
  const content = nodes.filter(n => n !== header && n !== footer);
  return { header, content, footer };
};

const getBackgroundImageUrl = (backgroundImage: BackgroundImage): string | undefined => {
  return (
    backgroundImage.media?.src.url ??
    (backgroundImage.media?.src.id
      ? getImageSrc({ file_name: backgroundImage.media.src.id }, undefined, {
          requiredQuality: 100,
          requiredWidth: Math.min(backgroundImage.media?.width ?? 4000, 4000),
          requiredHeight: Math.min(backgroundImage.media?.height ?? 4000, 4000),
        })
      : undefined)
  );
};

const getCardBackgroundStyles = (
  background?: Background,
  backgroundImage?: BackgroundImage
): CSSProperties => {
  const vars: Record<string, string> = {};

  // When any explicit background is set, block theme inheritance for all layers.
  // Zero-alpha color is the "cleared" state — it should inherit from theme.
  const isTransparentColor =
    background?.type === 'COLOR' && isTransparentCardBackgroundColor(background.color);
  const hasExplicitBackground = (!!background && !isTransparentColor) || !!backgroundImage;

  // When an image is set, `background` plays the role of the *overlay* (on top
  // of the image). Otherwise it's the card fill (color or gradient).
  if (backgroundImage) {
    const imageUrl = getBackgroundImageUrl(backgroundImage);
    if (imageUrl) {
      vars['--ricos-internal-card-background-image'] = `url(${imageUrl})`;
    }
    if (backgroundImage.scaling) {
      vars['--ricos-internal-card-background-size'] = backgroundImage.scaling.toLowerCase();
    }
    if (backgroundImage.position) {
      vars['--ricos-internal-card-background-position'] = backgroundImage.position
        .toLowerCase()
        .split('_')
        .join(' ');
    }

    // `backgroundImage.overlay` (new model) is authoritative when present; otherwise the legacy
    // `background` fill doubles as the overlay through the opacity shim.
    if (backgroundImage.overlay?.type === 'GRADIENT') {
      const css = gradientToCss(backgroundImage.overlay.gradient);
      if (css) {
        vars['--ricos-internal-card-background-image-overlay'] = css;
      }
    } else if (backgroundImage.overlay?.type === 'COLOR') {
      vars['--ricos-internal-card-background-image-overlay'] = hexToRgba(
        backgroundImage.overlay.color
      );
    } else if (background?.type === 'GRADIENT') {
      const css = gradientToCss(background.gradient);
      if (css) {
        vars['--ricos-internal-card-background-image-overlay'] = css;
      }
    } else if (background?.type === 'COLOR' && !isTransparentColor) {
      const resolved = resolveBackwardCompatOverlay(
        background.color,
        backgroundImage.opacity ?? 100,
        100
      );
      vars['--ricos-internal-card-background-image-overlay'] = hexToRgba(resolved);
    }
  } else {
    const backgroundColorCssVar = getCardBackgroundColorCssVar(background, hasExplicitBackground);
    if (backgroundColorCssVar) {
      vars['--ricos-internal-card-background-color'] = backgroundColorCssVar;
    }

    if (background?.type === 'GRADIENT') {
      const css = gradientToCss(background.gradient);
      if (css) {
        vars['--ricos-internal-card-background-gradient'] = css;
      }
    }

    if (hasExplicitBackground) {
      // Block theme image when card has explicit color/gradient but no image
      vars['--ricos-internal-card-background-image'] = 'none';
    }
  }

  return vars as CSSProperties;
};

type CardRendererOptions = Pick<
  CardPluginViewerConfig,
  'pageFormat' | 'renderCardHeader' | 'cardIndexOffset'
> & {
  mode: CardViewerMode;
};

type CardProps = NodeViewRendererProps &
  CardRendererOptions & {
    pageFormat?: string;
  };

const CardContent: FC<Pick<NodeViewRendererProps, 'node' | 'nodeIndex' | 'RicosNodesRenderer'>> = ({
  node,
  nodeIndex,
  RicosNodesRenderer,
}) => {
  const { header, content, footer } = splitCardChildren(node.nodes ?? []);

  return (
    <RicosNodeContextProvider parentNode={node} parentIndex={nodeIndex}>
      {header && (
        <div data-card-header>
          <RicosNodesRenderer nodes={[header]} isRoot />
        </div>
      )}
      <div data-card-content>
        <RicosNodesRenderer nodes={content} isRoot />
      </div>
      {footer && (
        <div data-card-footer>
          <RicosNodesRenderer nodes={[footer]} isRoot />
        </div>
      )}
    </RicosNodeContextProvider>
  );
};

const Card: FC<CardProps> = ({
  node,
  nodeIndex,
  RicosNodesRenderer,
  pageFormat,
  mode,
  renderCardHeader,
  cardIndexOffset = 0,
}) => {
  const pageSize = getPageSizeByFormat(pageFormat);
  const isFluid = pageSize.height === undefined;
  const cardData = node.cardData;
  // Null in editor mode, where the card is rendered outside RicosViewer.
  const { isPrint } = useContext(RicosViewerContext) ?? {};

  const style: CSSProperties = {
    '--ricos-internal-card-width': `${pageSize.width}px`,
    ...(pageSize.height !== undefined
      ? { '--ricos-internal-card-height': `${pageSize.height}px` }
      : {}),
    ...getCardBackgroundStyles(
      cardData?.background as Background | undefined,
      cardData?.backgroundImage as BackgroundImage | undefined
    ),
  } as CSSProperties;

  const header = renderCardHeader?.({
    cardNode: node as RichContentNode,
    index: nodeIndex + 1 + cardIndexOffset,
  } satisfies CardHeaderProps<RichContentNode>);

  if (mode === 'editor') {
    return (
      <div className={editorStyles.cardWrapper} data-hook="card-viewer-wrapper">
        {header && (
          <div className={editorStyles.cardHeaderContainer} data-hook="card-viewer-header">
            {header}
          </div>
        )}
        <div
          className={classNames(editorStyles.cardContainer, {
            [editorStyles.fluid]: isFluid,
          })}
          data-hook="card-viewer-container"
          style={style}
        >
          <div
            className={classNames(editorStyles.cardContent, {
              [editorStyles.fluidContent]: isFluid,
            })}
          >
            <CardContent
              node={node}
              nodeIndex={nodeIndex}
              RicosNodesRenderer={RicosNodesRenderer}
            />
          </div>
        </div>
        <div className={editorStyles.cardGap} data-hook="card-viewer-gap" />
      </div>
    );
  }

  const wrapperClassName = classNames(viewerStyles.cardWrapper, {
    [viewerStyles.fluid]: isFluid,
    [viewerStyles.print]: !!isPrint,
  });

  return (
    <div className={wrapperClassName} data-hook="card-viewer-wrapper">
      <div className={viewerStyles.cardContainer} data-hook="card-viewer-container" style={style}>
        <div className={viewerStyles.cardContent}>
          <CardContent node={node} nodeIndex={nodeIndex} RicosNodesRenderer={RicosNodesRenderer} />
        </div>
      </div>
      <div className={viewerStyles.pageSeparator} data-hook="card-viewer-separator" />
    </div>
  );
};

export const createCardRenderer = ({
  pageFormat,
  mode,
  renderCardHeader,
  cardIndexOffset,
}: CardRendererOptions): NodeViewRenderer => {
  return ({ node, ...props }) => (
    <Card
      key={node.id}
      node={node}
      pageFormat={pageFormat}
      mode={mode}
      renderCardHeader={renderCardHeader}
      cardIndexOffset={cardIndexOffset}
      {...props}
    />
  );
};
