import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { CodeBlockPluginViewerConfig } from './types.js';
import { CODE_BLOCK_TYPE } from './types.js';

export const pluginCodeBlock: ViewerPluginCreator<CodeBlockPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: CODE_BLOCK_TYPE,
  };
};
