import classNames from 'classnames';
import type { CSSProperties } from 'react';
import React, { useEffect } from 'react';

import type { ImageProps } from './../../bundled-dependencies/wix-image.js';
import { Image as ImageComp, initCustomElement } from './../../bundled-dependencies/wix-image.js';
import type { MediaUploadError } from './../../ricos-content/index.js';
import type { TFunction } from './../../ricos-types/index.js';

import styles from './Image-scss.js';
import { MediaItemErrorMsg } from './media-item-error-msg.js';

let wixImageInitialized = false;

type Props = Exclude<ImageProps, 'id' | 'containerId'> & {
  id?: string | number;
  containerProps?: {
    className?: string;
    containerId?: string;
    style?: CSSProperties;
    dataHook?: string;
  };
  error?: {
    t: TFunction;
    message: MediaUploadError;
  };
};

export const Image = (props: Props) => {
  if (!wixImageInitialized) {
    // To not break editor
    initCustomElement();
    wixImageInitialized = true;
  }
  const { containerProps, error, shouldUseLQIP: shouldUseLQIPProp = true, ...imageProps } = props;
  const [isPrinting, setIsPrinting] = React.useState(false);

  useEffect(() => {
    const handleBeforePrint = () => {
      setIsPrinting(true);
    };

    window.addEventListener('beforeprint', handleBeforePrint);

    return () => {
      window.removeEventListener('beforeprint', handleBeforePrint);
    };
  }, []);

  return (
    <div
      style={containerProps?.style}
      id={containerProps?.containerId}
      className={containerProps?.className}
      data-hook={containerProps?.dataHook}
    >
      <ImageComp
        {...imageProps}
        alignType="center"
        className={classNames(styles.image, imageProps.className)}
        shouldUseLQIP={shouldUseLQIPProp && !isPrinting}
      />
      {error && <MediaItemErrorMsg error={error.message} t={error.t} />}
    </div>
  );
};
