import classnames from 'classnames';
import React from 'react';

import { REVEAL_SPOILER_BTN } from './../../_shared/data-hooks.js';
import { Tooltip } from './../../wix-rich-content-common/lib/tooltip.js';

import { SpoilerContainerIcon } from '../icons/spoiler-container-icon.js';
import { RevealButton } from './reveal-button.js';
import { SpoilerDescriptionInput } from './spoiler-description-input.js';

type Props = {
  description?: string;
  buttonContent?: string;
  styles: Record<string, string>;
  pluginType?: string;
  onRevealSpoiler?: (...args: $TSFixMe[]) => void;
  setFocusToBlock?: (...args: $TSFixMe[]) => void;
  setInPluginEditingMode?: (...args: $TSFixMe[]) => void;
  width?: number;
  height?: number;
  handleDescriptionChange?: (...args: $TSFixMe[]) => void;
  handleButtonContentChange?: (...args: $TSFixMe[]) => void;
  t: (key: string) => string;
  isMobile?: boolean;
  helpers?: $TSFixMe;
};

export class SpoilerContainer extends React.Component<Props> {
  renderDescription(description: $TSFixMe) {
    const {
      setInPluginEditingMode,
      pluginType,
      styles,
      handleDescriptionChange,
      setFocusToBlock,
      t,
    } = this.props;

    return (
      <SpoilerDescriptionInput
        setInPluginEditingMode={setInPluginEditingMode}
        className={styles.spoilerDescription}
        value={description ?? t(`Spoiler_Reveal_${pluginType}_Placeholder`)}
        onChange={handleDescriptionChange}
        setFocusToBlock={setFocusToBlock}
      />
    );
  }

  getReducedContainer = (className: string) => {
    const { onRevealSpoiler, pluginType, t } = this.props;
    const disabledRevealBtn = !onRevealSpoiler;
    const container = (
      <SpoilerContainerIcon
        className={className}
        style={{ cursor: !disabledRevealBtn ? 'pointer' : 'auto', display: 'inline' }}
        onClick={onRevealSpoiler}
        data-hook={REVEAL_SPOILER_BTN}
      />
    );

    return disabledRevealBtn ? (
      container
    ) : (
      <Tooltip content={t(`Spoiler_Reveal_${pluginType}_CTA`)} hideArrow>
        {container}
      </Tooltip>
    );
  };

  getExpandedContainer = (containerClassName: string) => {
    const {
      description,
      buttonContent,
      pluginType,
      onRevealSpoiler,
      styles,
      setInPluginEditingMode,
      setFocusToBlock,
      handleButtonContentChange,
      isMobile,
      t,
    } = this.props;
    const disabledRevealBtn = !onRevealSpoiler;
    const content = buttonContent ?? t(`Spoiler_Reveal_${pluginType}_CTA`);
    const buttonClassName = classnames(styles.revealSpoilerBtn, {
      [styles.revealSpoilerBtnMobile]: isMobile,
      [styles.onHoverBtn]: !disabledRevealBtn,
    });
    return (
      <div className={containerClassName} style={{ width: '100%' }}>
        <SpoilerContainerIcon
          style={{ cursor: !disabledRevealBtn ? 'pointer' : 'auto', display: 'inline' }}
          onClick={onRevealSpoiler}
        />
        {this.renderDescription(description)}
        <RevealButton
          onRevealSpoiler={onRevealSpoiler}
          className={buttonClassName}
          value={content}
          onChange={handleButtonContentChange}
          setInPluginEditingMode={setInPluginEditingMode}
          setFocusToBlock={setFocusToBlock}
        />
      </div>
    );
  };

  render() {
    const { pluginType, width, height, styles } = this.props;
    const containerClassName =
      pluginType === 'Gallery' ? styles.spoilerContainer_Gallery : styles.spoilerContainer;
    const spoilerContainer =
      (width ?? Infinity) < 320 || (height ?? Infinity) < 228
        ? this.getReducedContainer(containerClassName)
        : this.getExpandedContainer(containerClassName);
    return spoilerContainer;
  }
}
