import {
  getThemeColorTokenOpacity,
  isThemeColorToken,
  setThemeColorTokenOpacity,
  stripThemeColorTokenOpacity,
  themeColorTokenToCssVar,
} from './../_shared/theme-color-token.js';

// Shade ratios taken from the Wixel platform to match their shade auto-generation calculations
const SHADES_RATIOS = { shade1: 0.1, shade2: 0.3, shade3: 0.5 };

const HEX_COLOR_RE = /^#?([0-9a-fA-F]{6})$/;

const parseHexToRgb = (hex: string) => {
  const match = hex.match(HEX_COLOR_RE);
  if (!match) {
    return { r: 0, g: 0, b: 0 };
  }
  const h = match[1];
  return {
    r: parseInt(h.substring(0, 2), 16),
    g: parseInt(h.substring(2, 4), 16),
    b: parseInt(h.substring(4, 6), 16),
  };
};

const rgbToHexString = ({ r, g, b }: { r: number; g: number; b: number }) => {
  const toHex = (v: number) => Math.round(v).toString(16).padStart(2, '0');
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
};

const clampChannel = (v: number) => Math.round(Math.min(255, Math.max(0, v)));

const mixChannels = (
  dark: { r: number; g: number; b: number },
  light: { r: number; g: number; b: number },
  darkRatio: number
) => ({
  r: clampChannel(darkRatio * dark.r + (1 - darkRatio) * light.r),
  g: clampChannel(darkRatio * dark.g + (1 - darkRatio) * light.g),
  b: clampChannel(darkRatio * dark.b + (1 - darkRatio) * light.b),
});

/**
 * Calculates shade colors by mixing base1 (light) and base2 (dark).
 * Matches the wixel platform's shade auto-generation logic.
 */
export const calculateShades = (lightHex: string, darkHex: string): [string, string, string] => {
  const light = parseHexToRgb(lightHex);
  const dark = parseHexToRgb(darkHex);
  return [
    rgbToHexString(mixChannels(dark, light, SHADES_RATIOS.shade1)),
    rgbToHexString(mixChannels(dark, light, SHADES_RATIOS.shade2)),
    rgbToHexString(mixChannels(dark, light, SHADES_RATIOS.shade3)),
  ];
};

export const hexToRgba = (alphaHex?: string, opacity?: number): string => {
  if (!alphaHex) {
    return '';
  }
  if (isThemeColorToken(alphaHex)) {
    const effectiveOpacity = opacity ?? getThemeColorTokenOpacity(alphaHex);
    if (effectiveOpacity < 100) {
      const tupleVar = themeColorTokenToCssVar(alphaHex, 'rgbTuple');
      return `rgba(${tupleVar}, ${effectiveOpacity / 100})`;
    }
    return themeColorTokenToCssVar(alphaHex);
  }

  const opacityPercentage = opacity ?? getOpacityFromHex(alphaHex);
  let hexColor = getHexColorFromAlpha(alphaHex)?.replace(/^#/, '') ?? '';

  if (hexColor.length === 3) {
    hexColor = hexColor
      .split('')
      .map((char: string) => char + char)
      .join('');
  }

  const bigint = parseInt(hexColor, 16);
  // oxlint-disable-next-line no-bitwise
  const r = (bigint >> 16) & 255;
  // oxlint-disable-next-line no-bitwise
  const g = (bigint >> 8) & 255;
  // oxlint-disable-next-line no-bitwise
  const b = bigint & 255;

  return `rgba(${r}, ${g}, ${b}${
    opacityPercentage !== undefined ? `, ${opacityPercentage / 100}` : ''
  })`;
};

export const combineHexWithOpacity = (
  hexColor: string | null | undefined,
  opacityPercentage: number
): string | undefined => {
  if (!hexColor) {
    return;
  }
  if (isThemeColorToken(hexColor)) {
    return setThemeColorTokenOpacity(hexColor, opacityPercentage);
  }

  const alpha = Math.round((opacityPercentage / 100) * 255);
  const alphaHex = alpha.toString(16).padStart(2, '0').toUpperCase();

  return `${hexColor?.slice(0, 7)}${alphaHex}`;
};

export const getOpacityFromHex = (hexColorWithAlpha: string | undefined | null): number => {
  if (isThemeColorToken(hexColorWithAlpha)) {
    return getThemeColorTokenOpacity(hexColorWithAlpha);
  }
  if (!hexColorWithAlpha || hexColorWithAlpha.length === 7) {
    return 100;
  }

  const hex = hexColorWithAlpha.replace('#', '');

  const alphaHex = hex.slice(6, 8);
  const alphaDecimal = parseInt(alphaHex, 16);
  return Math.round((alphaDecimal / 255) * 100);
};

export const getHexColorFromAlpha = (hexColorWithAlpha: string | undefined): string | undefined => {
  if (isThemeColorToken(hexColorWithAlpha)) {
    return stripThemeColorTokenOpacity(hexColorWithAlpha);
  }
  if (!hexColorWithAlpha || hexColorWithAlpha.length === 7) {
    return hexColorWithAlpha;
  }

  return hexColorWithAlpha.slice(0, 7);
};
