import type { FileSource } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import type { ImagePluginViewerConfig } from '../viewer-loadable.js';

export const useImageSocialAttributes = ({
  src,
  config,
  width,
  height,
}: {
  src: FileSource | undefined;
  config: ImagePluginViewerConfig | undefined;
  width: number | undefined;
  height: number | undefined;
}) => {
  if (src === undefined || config?.imageProps === undefined) {
    return {};
  }
  const imageProps =
    typeof config.imageProps === 'function'
      ? config.imageProps({ url: src.url, file_name: src.id, width, height })
      : config.imageProps;

  return ['data-pin-nopin', 'data-pin-url', 'data-pin-media'].reduce(
    (socialAttributes: $TSFixMe, attribute) => {
      if (imageProps[attribute as keyof typeof imageProps]) {
        return {
          ...socialAttributes,
          [attribute]: imageProps[attribute as keyof typeof imageProps],
        };
      }
      return socialAttributes;
    },
    {} as Record<string, string>
  );
};
