import type { ImageData_CropShape } from './../ricos-schema/next-schema/index.js';
import { svgToDataUri } from './../_shared/svg-to-data-uri.js';

import CircleMaskSvg from './clip-masks/circle.js';
import FluidMaskSvg from './clip-masks/fluid.js';
import HeartMaskSvg from './clip-masks/heart.js';
import HexagonMaskSvg from './clip-masks/hexagon.js';
import OvalMaskSvg from './clip-masks/oval.js';
import PentagonMaskSvg from './clip-masks/pentagon.js';
import RhombusMaskSvg from './clip-masks/rhombus.js';
import StarMaskSvg from './clip-masks/star.js';
import TriangleMaskSvg from './clip-masks/triangle.js';
import WindowMaskSvg from './clip-masks/window.js';

/**
 * Alpha masks for shape crops, applied as `mask-image` by the viewer (`viewer/image.tsx`)
 * and by the crop overlay preview.
 *
 * `clip-masks/*.svg` are inlined as text modules at build time, so the data URIs resolve at
 * module scope: the viewer builds the mask into an inline style during render, and it has to
 * be available synchronously for SSR.
 *
 * Authoring rules for `clip-masks/*.svg`:
 * - `width`/`height`/`viewBox` are load-bearing — `mask-size: contain` derives the shape's
 *   aspect ratio from them.
 * - No `fill`: the SVG default is opaque black, which is all an alpha mask needs
 *   (`viewer/image.tsx` sets `mask-mode: alpha`, so hue is irrelevant).
 * - The `stroke` on `oval.svg` and `hexagon.svg` is load-bearing — both shapes are inset and
 *   stroked back out to the edge of the box.
 * - Single-quoted attributes, kept on one line: `"` would be escaped to `%22` inside
 *   `url("…")`, and `svgToDataUri` collapses whitespace, so indentation would only survive
 *   as payload-inflating spaces between tags.
 */
const SHAPE_SVG_DATA_URLS: Record<ImageData_CropShape, string> = {
  CIRCLE: svgToDataUri(CircleMaskSvg),
  OVAL: svgToDataUri(OvalMaskSvg),
  TRIANGLE: svgToDataUri(TriangleMaskSvg),
  STAR: svgToDataUri(StarMaskSvg),
  HEART: svgToDataUri(HeartMaskSvg),
  HEXAGON: svgToDataUri(HexagonMaskSvg),
  PENTAGON: svgToDataUri(PentagonMaskSvg),
  RHOMBUS: svgToDataUri(RhombusMaskSvg),
  FLUID: svgToDataUri(FluidMaskSvg),
  WINDOW: svgToDataUri(WindowMaskSvg),
};

export const getShapeCropMaskDataUri = (cropShape?: ImageData_CropShape | null) =>
  cropShape ? SHAPE_SVG_DATA_URLS[cropShape] : undefined;
