import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { NodeViewRenderers, ViewerPluginCreator } from './../ricos-types/index.js';

import { createCardRenderer } from './card-viewer.js';
import type { CardPluginViewerConfig } from './types.js';

export const pluginCardViewer: ViewerPluginCreator<CardPluginViewerConfig> = config => {
  const nodeViewRenderers: NodeViewRenderers = {
    [Node_Type.CARD]: createCardRenderer({
      pageFormat: config?.pageFormat,
      mode: config?.mode ?? 'viewer',
      renderCardHeader: config?.renderCardHeader,
      cardIndexOffset: config?.cardIndexOffset,
    }),
  };

  return {
    config: { ...config },
    type: Node_Type.CARD,
    nodeViewRenderers,
  };
};
