/* oxlint-disable jsx-a11y/no-static-element-interactions */
import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { COLLAPSIBLE_LIST_ITEM, EXPAND_BUTTON } from '../data-hooks.js';
import { ArrowIcon } from '../icons/index.js';
import iconStyles from '../statics/styles/collapsible-list-component-scss.js';
import classes from '../statics/styles/collapsible-list-pair-scss.js';
import { CollapsibleListContext } from './collapsible-list-context.js';

const CollapsibleListItem = ({ node, RicosNodesRenderer }: NodeViewRendererProps) => {
  const { isExpanded: isItemExpanded, toggle } = useContext(CollapsibleListContext);
  const { tabIndex } = useContext(RicosContext);
  const isExpanded = isItemExpanded(node.id);

  if (!node.nodes || node.nodes.length === 0) {
    // AI Streaming case
    return null;
  }
  const [firstChild, ...restOfChildren] = node.nodes ?? [];
  const bodyId = `collapsible-list-body-${node.id}`;

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === ' ') {
      event.preventDefault();
    }
  };

  const handleKeyUp = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === ' ' || event.key === 'Enter') {
      toggle(node.id);
    }
  };

  return (
    <div>
      <div data-hook={`${COLLAPSIBLE_LIST_ITEM} ${isExpanded ? 'expanded' : 'collapsed'}`}>
        <div className={classNames(classes.itemContainer, classes.itemContainerViewer)}>
          <div className={classes.item}>
            <div
              className={classNames(classes.itemHeader, 'has-custom-focus')}
              role="button"
              tabIndex={tabIndex}
              onClick={() => toggle(node.id)}
              onKeyDown={handleKeyDown}
              onKeyUp={handleKeyUp}
              aria-expanded={isExpanded}
              aria-controls={bodyId}
            >
              <div className={classes.expandIcon}>
                <div
                  className={iconStyles.iconContainer}
                  data-hook={EXPAND_BUTTON}
                  aria-hidden="true"
                >
                  <ArrowIcon
                    className={classNames(iconStyles.icon, {
                      [iconStyles.isExpanded]: isExpanded,
                    })}
                  />
                </div>
              </div>
              <div className={classes.item}>
                <RicosNodesRenderer nodes={[firstChild]} />
              </div>
            </div>
            <div
              id={bodyId}
              className={classNames(
                classes.itemBody,
                isExpanded ? undefined : classes.childrenHidden
              )}
            >
              <div className={classes.expandIconPlaceholder} />
              <div className={classes.item}>
                <RicosNodesRenderer nodes={restOfChildren} />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const CollapsibleListItemRenderer = ({ node, ...props }: NodeViewRendererProps) => {
  return <CollapsibleListItem key={node.id} node={node} {...props} />;
};

export default CollapsibleListItemRenderer;
