import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosNodeContext } from './../../ricos-context/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { COLLAPSIBLE_LIST_ITEM_BODY, COLLAPSIBLE_LIST_ITEM_TITLE } from '../data-hooks.js';
import classes from '../statics/styles/collapsible-list-pair-scss.js';
import { getAlignmentFromDirection } from '../utils.js';

const CollapsibleListItemProperty = ({
  node,
  RicosNodesRenderer,
  type,
}: NodeViewRendererProps & { type: 'title' | 'body' }) => {
  const { parentNode: rootNode } = useContext(RicosNodeContext);

  const rootNodeDirection = rootNode?.collapsibleListData?.direction;
  const listAlignment = rootNodeDirection
    ? getAlignmentFromDirection(rootNodeDirection)
    : undefined;

  return (
    <div
      className={classNames(classes.container, classes.viewerContainer, classes.innerEditor, {
        [classes.titleContainer]: type === 'title',
      })}
      data-hook={type === 'title' ? COLLAPSIBLE_LIST_ITEM_TITLE : COLLAPSIBLE_LIST_ITEM_BODY}
    >
      <div
        style={{
          width: '100%',
          textAlign: listAlignment,
        }}
      >
        <RicosNodesRenderer nodes={node.nodes ?? []} shouldParagraphApplyTextStyle />
      </div>
    </div>
  );
};

export const CollapsibleListItemTitleProperty = ({ node, ...props }: NodeViewRendererProps) => {
  return <CollapsibleListItemProperty key={node.id} node={node} {...props} type="title" />;
};

export const CollapsibleListItemBodyProperty = ({ node, ...props }: NodeViewRendererProps) => {
  return <CollapsibleListItemProperty key={node.id} node={node} {...props} type="body" />;
};

export default CollapsibleListItemProperty;
