import type { CSSProperties } from 'react';

import type { ImageData_Crop } from './../../ricos-schema/next-schema/index.js';
import { isCropped, normalize } from './../../_shared/media/image-crop.js';

type CropRenderData = {
  width: number;
  height: number;
  fullImageStyle: CSSProperties;
};

/** Returns cropped dimensions plus the CSS fallback layer style for non-transformable sources. */
export const getCropRenderData = ({
  crop,
  naturalWidth,
  naturalHeight,
}: {
  crop?: ImageData_Crop | null;
  naturalWidth: number | undefined;
  naturalHeight: number | undefined;
}): CropRenderData | null => {
  if (!isCropped(crop) || !naturalWidth || !naturalHeight) {
    return null;
  }

  const { x, y, width, height } = normalize(crop);

  return {
    width: width * naturalWidth,
    height: height * naturalHeight,
    fullImageStyle: {
      position: 'absolute',
      width: `${100 / width}%`,
      height: `${100 / height}%`,
      left: `${-(x / width) * 100}%`,
      top: `${-(y / height) * 100}%`,
    },
  };
};
