import type { LinkType } from './../_shared/link-modal/open-link-modal/types.js';

export const LINK_TYPE = 'LINK';

export interface LinkPluginEditorConfig {
  type: 'link';
  autoLink?: boolean;
  /**
   * Link types available in the link modal.
   *
   * Note: when page links (site-pages) are enabled here, the `baseUrl` prop must be
   * passed to `RicosViewerProps` for page URLs to resolve correctly.
   */
  enabledLinkTypes?: LinkType[];
  /** @deprecated this property does nothing but is provided by some consumers. So please remove it, so we can delete this*/
  linkTypes?: any;
}
export interface LinkPluginViewerConfig {
  onClick?: (event: any, url: any) => void;
  siteUrl?: string;
}
