import React, { useContext } from 'react';

import { RicosViewerContext } from './../../ricos-context/index.js';
import type { HTMLData } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { HTML_TYPE } from '../types.js';
import { HtmlViewer } from './html-viewer.js';

const Html = ({ node, nodeIndex, NodeViewContainer }: NodeViewRendererProps) => {
  const { iframeSandboxDomain, config } = useContext(RicosViewerContext);
  const pluginConfig = config[HTML_TYPE] ?? {};

  return (
    <NodeViewContainer node={node} nodeIndex={nodeIndex}>
      <HtmlViewer
        htmlData={node.htmlData as HTMLData}
        settings={pluginConfig}
        iframeSandboxDomain={iframeSandboxDomain}
        isViewer
      />
    </NodeViewContainer>
  );
};

export default Html;
