import React, { Component } from 'react';

import { SPOILER_TEXT_AREA } from './../../_shared/data-hooks.js';

import { EditableTextInput as EditableInputWrapper } from './editable-input-wrapper.js';

type Props = {
  className?: string;
  value: string;
  onChange?: (value: string) => void;
  setFocusToBlock?: () => void;
  setInPluginEditingMode?: (shouldEnable: boolean) => void;
};

export class SpoilerDescriptionInput extends Component<Props> {
  componentDidUpdate() {
    this.fixTextAreaHeight();
  }

  fixTextAreaHeight() {
    // @ts-expect-error
    if (this.textAreaRef?.style) {
      // @ts-expect-error
      this.textAreaRef.style.height = '';
      // @ts-expect-error
      this.textAreaRef.style.height = this.textAreaRef.scrollHeight + 'px';
    }
  }

  onChange = (e: $TSFixMe) => this.props.onChange?.(e.target.value);

  // @ts-expect-error
  setTextAreaRef = (ref: $TSFixMe) => (this.textAreaRef = ref);

  render() {
    const { className, onChange, value, setFocusToBlock, setInPluginEditingMode } = this.props;

    const InputComponent = (
      <textarea
        ref={this.setTextAreaRef}
        className={className}
        rows={1}
        maxLength={70}
        data-hook={SPOILER_TEXT_AREA}
      />
    );

    return onChange ? (
      <EditableInputWrapper
        InputComponent={InputComponent}
        value={value}
        onChange={this.onChange}
        setInPluginEditingMode={setInPluginEditingMode ?? (() => {})}
        setFocusToBlock={setFocusToBlock ?? (() => {})}
      />
    ) : (
      <span className={className} dir="auto" style={{ display: 'block', maxWidth: '89%' }}>
        {value}
      </span>
    );
  }
}
