export const FONT_FAMILY_TYPE = 'fontFamily';

export type FontFamilyPluginEditorConfig = {
  type: 'fontFamily';
  // font loading is consumer's responsibility
  FontFamilyPicker?: FontFamilyPickerType;
  getFontFamilyLabel?: (family: string) => string;
  fallbackFontFamily?: string;
};

export type FontFamilyPluginViewerConfig = {
  // The viewer just wraps the text node with span and applies the font-family style.
  // Font loading is consumer's responsibility
  fallbackFontFamily?: string;
};

export type FontFamilyPickerType = React.FC<{
  current?: string;
  onChange: (fontFamily: string) => void;
}>;
