import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { LinkPreviewPluginViewerConfig } from './types.js';
import { LINK_PREVIEW_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export const pluginLinkPreview: ViewerPluginCreator<LinkPreviewPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: LINK_PREVIEW_TYPE,
    nodeViewRenderers,
  };
};
