import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULT_CONFIGS } from './defaults.js';
import type { VideoPluginViewerConfig } from './types.js';
import { VIDEO_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export const pluginVideo: ViewerPluginCreator<VideoPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULT_CONFIGS.viewer, ...config },
    type: VIDEO_TYPE,
    nodeViewRenderers,
  };
};
