import React from 'react';

import type { Decoration, Node } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { NodeViewDecorator } from './../ricos-types/index.js';

import { withFallbackFontFamily } from './with-fallback-font-family.js';

export const nodeViewDecorator = (fallbackFontFamily?: string): NodeViewDecorator<JSX.Element> => ({
  rule: (node: Node) =>
    !!node.textData?.decorations?.find(
      (dec: Decoration) => dec.type === Decoration_Type.FONT_FAMILY
    ),
  decorate: ({ element, node }) => {
    const fontFamily = node.textData?.decorations?.find(
      (dec: Decoration) => dec.type === Decoration_Type.FONT_FAMILY
    )?.fontFamilyData?.value;

    return (
      <span style={{ fontFamily: withFallbackFontFamily(fontFamily, fallbackFontFamily) }}>
        {element}
      </span>
    );
  },
});
