import { useLayoutEffect, useState } from 'react';

import type { ImageNode, PluginContainerData } from './../../ricos-schema/next-schema/index.js';
import { isSSR } from './../../wix-rich-content-common/index.js';

export const useImageDimensions = ({
  src,
  containerData,
  image,
  loadMissingDimensions = true,
}: {
  src: string | undefined;
  containerData: PluginContainerData;
  image: NonNullable<ImageNode['imageData']>['image'] | undefined;
  loadMissingDimensions?: boolean;
}) => {
  const [dimensions, setDimensions] = useState<{
    width: number | undefined;
    height: number | undefined;
  }>({
    width: undefined,
    height: undefined,
  });

  const width = image?.width ?? (Number(containerData?.width?.custom) || dimensions.width);
  const height = image?.height ?? (Number(containerData?.height?.custom) || dimensions.height);

  useIsomorphicLayoutEffect(() => {
    if (typeof width === 'number' && typeof height === 'number') {
      return;
    }
    setDimensions({ width: undefined, height: undefined });
    if (!src || !loadMissingDimensions) {
      return;
    }

    const newImg = new Image();
    newImg.onload = () => setDimensions({ width: newImg.width, height: newImg.height });
    newImg.src = src;

    return () => {
      newImg.onload = null;
    };
  }, [src, loadMissingDimensions]);

  return {
    width,
    height,
  };
};

// to silence Reacts warning
const useIsomorphicLayoutEffect: typeof useLayoutEffect = isSSR() ? () => {} : useLayoutEffect;
