/* oxlint-disable jsx-a11y/no-static-element-interactions */
import classNames from 'classnames';
import type { FC } from 'react';
import React, { useCallback, useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { ButtonData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { ButtonData_Type, Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Gradient, Helpers, LegacyEditorPluginConfig } from './../../ricos-types/index.js';
import { getLinkHrefUrl } from './../../_shared/link/get-link-href-url.js';
import { resolveCssColor } from './../../_shared/resolve-css-color.js';
import { schemaGradientToCss } from './../../_shared/schema-gradient-to-css.js';
import { getRelValue } from './../../wix-rich-content-common/index.js';

import { ROOT } from '../data-hooks.js';
import styles from '../statics/styles/default-styles-scss.js';
import { ACTION_BUTTON_TYPE, LINK_BUTTON_TYPE } from '../types.js';

interface ButtonViewerProps {
  onClick?: () => void;
  className?: string;
  helpers?: Helpers;
  settings: LegacyEditorPluginConfig;
  buttonData: ButtonData;
  nodeId: string;
  baseUrl?: string;
}

export const ButtonViewer: FC<ButtonViewerProps> = ({
  onClick,
  className,
  helpers,
  settings = {},
  buttonData,
  nodeId,
  baseUrl,
}) => {
  const { tabIndex, theme } = useContext(RicosContext);
  const isActionButton = buttonData.type === ButtonData_Type.ACTION;
  const onClickHandler = useCallback(() => {
    helpers?.onViewerAction?.(
      isActionButton ? ACTION_BUTTON_TYPE : LINK_BUTTON_TYPE,
      'Click',
      '',
      nodeId,
      {
        type: Node_Type.BUTTON,
        buttonData,
      }
    );
    onClick?.();
  }, [helpers?.onViewerAction]);
  const ButtonComponent = settings.customComponent
    ? settings.customComponent
    : isActionButton
      ? ActionButton
      : LinkButton;

  const btnStyles = buttonData?.styles;

  const borderWidth = btnStyles?.borderWidth ?? btnStyles?.border?.width ?? 0;
  const borderRadius = btnStyles?.borderRadius ?? btnStyles?.border?.radius;
  const normalBorderColor =
    btnStyles?.borderColor ?? btnStyles?.colors?.border ?? settings.colors?.color8 ?? '';
  const hoverBorderColor =
    btnStyles?.borderColorHover ??
    (theme?.customStyles?.button?.borderColorHover ? undefined : normalBorderColor);
  const normalTextColor =
    btnStyles?.textColor ?? btnStyles?.colors?.text ?? settings.colors?.color1;
  const hoverTextColor =
    btnStyles?.textColorHover ??
    (theme?.customStyles?.button?.colorHover ? undefined : normalTextColor);

  const background = btnStyles?.background;
  const backgroundHover = btnStyles?.backgroundHover;

  const normalBackgroundColor =
    (background?.type === 'COLOR' ? background.color : undefined) ??
    btnStyles?.backgroundColor ??
    btnStyles?.colors?.background ??
    settings.colors?.color8;
  const hoverBackgroundColor =
    (backgroundHover?.type === 'COLOR' ? backgroundHover.color : undefined) ??
    btnStyles?.backgroundColorHover ??
    (theme?.customStyles?.button?.backgroundColorHover ? undefined : normalBackgroundColor);
  const customWidth = buttonData.containerData?.width?.custom;
  const isSmallButton = btnStyles?.buttonSize
    ? btnStyles?.buttonSize === 'SMALL'
    : theme?.customStyles?.button?.buttonSize === 'small';
  const isLargeButton = btnStyles?.buttonSize
    ? btnStyles?.buttonSize === 'LARGE'
    : theme?.customStyles?.button?.buttonSize === 'large';
  const fontSize = isSmallButton ? 12 : isLargeButton ? 16 : undefined;
  const padding = isSmallButton ? '6px 9px' : isLargeButton ? '15px 24px' : undefined;

  const normalBackground =
    background?.type === 'GRADIENT'
      ? schemaGradientToCss(background.gradient as Gradient)
      : normalBackgroundColor;
  const hoverBackground =
    backgroundHover?.type === 'GRADIENT'
      ? schemaGradientToCss(backgroundHover.gradient as Gradient)
      : resolveCssColor(hoverBackgroundColor);

  const style = {
    '--ricos-internal-button-color': resolveCssColor(normalTextColor),
    ...(hoverTextColor
      ? { '--ricos-internal-button-color-hover': resolveCssColor(hoverTextColor) }
      : {}),
    '--ricos-internal-button-background':
      background?.type === 'GRADIENT' ? normalBackground : resolveCssColor(normalBackgroundColor),
    ...(hoverBackground ? { '--ricos-internal-button-background-hover': hoverBackground } : {}),
    ...(normalBorderColor
      ? { '--ricos-internal-button-border-color': resolveCssColor(normalBorderColor) }
      : {}),
    ...(hoverBorderColor
      ? { '--ricos-internal-button-border-color-hover': resolveCssColor(hoverBorderColor) }
      : {}),
    '--ricos-internal-button-border-radius': borderRadius ? `${borderRadius}px` : undefined,
    '--ricos-internal-button-border-width': borderWidth ? `${borderWidth}px` : undefined,
    '--ricos-internal-button-custom-width': customWidth ? `${customWidth}px` : undefined,
    '--ricos-internal-button-font-size': fontSize ? `${fontSize}px` : undefined,
    '--ricos-internal-button-padding': padding,
    printColorAdjust: 'exact',
  };

  return (
    <ButtonComponent
      className={classNames(styles.button_container, className)}
      style={style}
      data-hook={`${ROOT} ${ROOT}-${nodeId}`}
      onClick={onClickHandler}
      tabIndex={tabIndex}
      buttonData={buttonData}
      {...(!isActionButton && {
        href: buttonData.link ? getLinkHrefUrl(buttonData.link, baseUrl) : undefined,
        target: buttonData.link?.target && `_${buttonData.link.target.toLowerCase()}`,
        rel: buttonData.link?.rel?.nofollow ? getRelValue('nofollow') : undefined,
      })}
    />
  );
};

const LinkButton: React.FC<ButtonViewerProps> = props => {
  const { buttonData, ...rest } = props;
  return (
    <a
      {...rest}
      onKeyDown={e => {
        if (e.key === 'Enter') {
          props.onClick?.();
        }
      }}
    >
      <div className={styles.button_text}>{buttonData.text}</div>
    </a>
  );
};

const ActionButton: React.FC<ButtonViewerProps> = props => {
  const { buttonData, ...rest } = props;
  return (
    <button
      {...rest}
      type="button"
      onKeyDown={e => {
        if (e.key === ' ' || e.key === 'Enter') {
          props.onClick?.();
        }
      }}
    >
      <div className={styles.button_text}>{buttonData.text}</div>
    </button>
  );
};
