import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { SpoilerViewerWrapper } from './Components/Wrappers/spoiler-viewer-wrapper.js';
import nodeViewDecorator from './node-view-decorator.js';
import type { SpoilerPluginViewerConfig } from './types.js';
import { SPOILER_TYPE } from './types.js';
import { initSpoilersContentState } from './utils/spoiler-utils-fn.js';

export { initSpoilersContentState, SpoilerViewerWrapper };

export const pluginSpoiler: ViewerPluginCreator<SpoilerPluginViewerConfig> = config => {
  return {
    config: { initSpoilersContentState, SpoilerViewerWrapper, ...config },
    type: SPOILER_TYPE,
    nodeViewDecorators: [nodeViewDecorator],
  };
};
