import React from 'react';

import { REVEAL_SPOILER_BTN, REVEAL_SPOILER_CONTENT } from './../../_shared/data-hooks.js';

import { EditableTextInput as EditableInputWrapper } from './editable-input-wrapper.js';

type Props = {
  className?: string;
  value: string;
  onChange?: (value: string) => void;
  setFocusToBlock?: () => void;
  setInPluginEditingMode?: (shouldEnable: boolean) => void;
  onRevealSpoiler?: (...args: $TSFixMe[]) => void;
};

export class RevealButton extends React.Component<Props> {
  onChange = (e: $TSFixMe) => {
    const oldValue = this.props.value;
    const newValue = e.target.value;
    if (e.target.scrollWidth < 229 || oldValue.length > newValue.length) {
      this.props.onChange?.(newValue);
    }
  };

  render() {
    const { className, onRevealSpoiler, setInPluginEditingMode, setFocusToBlock, value, onChange } =
      this.props;

    const InputComponent = (
      <input size={value.length + 1} data-hook={REVEAL_SPOILER_CONTENT} type="text" />
    );

    return (
      <button
        className={className}
        onClick={onRevealSpoiler}
        data-hook={REVEAL_SPOILER_BTN}
        type="button"
      >
        {onChange ? (
          <EditableInputWrapper
            InputComponent={InputComponent}
            value={value}
            onChange={this.onChange}
            setInPluginEditingMode={setInPluginEditingMode ?? (() => {})}
            setFocusToBlock={setFocusToBlock ?? (() => {})}
          />
        ) : (
          <span dir="auto">{value}</span>
        )}
      </button>
    );
  }
}
