import type { EditorPluginConfig, ViewerPluginConfig } from './../ricos-types/index.js';

export const LINE_SPACING_TYPE = 'line-spacing';

export interface LineSpacingPluginEditorConfig extends EditorPluginConfig {
  type: 'lineSpacing';
  [key: string]: any; // oxlint-disable-line @typescript-oxlint/no-explicit-any
  inlinePopups?: boolean;
  defaultSpacing?: LineSpacings;
}
export interface LineSpacingPluginViewerConfig extends ViewerPluginConfig {
  [key: string]: any; // oxlint-disable-line @typescript-oxlint/no-explicit-any
  defaultSpacing?: LineSpacings;
}

export type LineSpacings = {
  'line-height': string;
  'padding-bottom': string;
  'padding-top': string;
};
