import React, { useContext } from 'react';

import { RicosViewerContext } from './../../ricos-context/index.js';
import type { EmbedNode } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { LINK_PREVIEW_TYPE } from '../types.js';
import { EmbedViewer } from './embed-viewer.js';

export const Embed = ({ node, nodeIndex, NodeViewContainer }: NodeViewRendererProps) => {
  const { iframeSandboxDomain, config } = useContext(RicosViewerContext);
  return (
    <NodeViewContainer node={node} nodeIndex={nodeIndex}>
      <EmbedViewer
        node={node as EmbedNode}
        settings={config[LINK_PREVIEW_TYPE]}
        iframeSandboxDomain={iframeSandboxDomain || ''}
      />
    </NodeViewContainer>
  );
};

// For loadable component
export default Embed;
