import React, { useContext } from 'react';

import { RicosViewerContext } from './../../ricos-context/index.js';
import type { NodeViewRenderer, NodeViewRendererProps } from './../../ricos-types/index.js';

import { ViewerFigure } from '../../_shared/figure/viewer-figure.js';
import { VIDEO_ROOT } from '../data-hooks.js';
import styles from '../statics/styles/video-viewer-scss.js';
import { VIDEO_TYPE } from '../types.js';
import { Video } from './video.js';

const ViewerVideo = ({
  node,
  nodeIndex,
  NodeViewContainer,
  RicosNodesRenderer,
}: NodeViewRendererProps) => {
  const { seoMode, config, jsdomMode } = useContext(RicosViewerContext);
  const { videoData } = node;

  if (!videoData) {
    return null;
  }

  return (
    <ViewerFigure
      node={node}
      nodeIndex={nodeIndex}
      NodeViewContainer={NodeViewContainer}
      RicosNodesRenderer={RicosNodesRenderer}
    >
      <div className={styles.video_container} data-hook={VIDEO_ROOT}>
        <Video
          config={config[VIDEO_TYPE] || {}}
          componentData={videoData}
          nodeId={node.id}
          seoMode={!!seoMode}
          jsdomMode={jsdomMode}
          isLight
        />
      </div>
    </ViewerFigure>
  );
};

const VideoRenderer: NodeViewRenderer = ({ node, ...props }) => {
  return <ViewerVideo key={node.id} node={node} {...props} />;
};

export default VideoRenderer;
