const stripQuotes = (fontFamily: string) => fontFamily.trim().replace(/^['"]|['"]$/g, '');

const splitFontFamilies = (fontFamily: string) =>
  fontFamily
    .split(',')
    .map(token => token.trim())
    .filter(Boolean);

const hasFallbackFontFamily = (fontFamily: string, fallbackFontFamily: string) =>
  splitFontFamilies(fontFamily).some(
    token => stripQuotes(token) === stripQuotes(fallbackFontFamily)
  );

export const withFallbackFontFamily = (
  fontFamily: string | undefined,
  fallbackFontFamily?: string
) => {
  if (!fontFamily || !fallbackFontFamily || hasFallbackFontFamily(fontFamily, fallbackFontFamily)) {
    return fontFamily;
  }

  return `${fontFamily}, ${fallbackFontFamily}`;
};
